        local now = tick()
        if now - lastFeedback < FEEDBACK_COOLDOWN then
            pcall(function() fbStatus:SetText(string.format("Aguarde %d segundos antes de enviar novamente.", math.ceil(FEEDBACK_COOLDOWN - (now - lastFeedback)))) end)
            return
        end
        local ftype = tostring((Opt.FeedbackType and Opt.FeedbackType.Value) or "Suggestion"):lower()
        local msg = fbTrim((Opt.FeedbackMsg and Opt.FeedbackMsg.Value) or "")
        if msg == "" then pcall(function() fbStatus:SetText("A mensagem está vazia.") end); return end
        if #msg > 500 then pcall(function() fbStatus:SetText("A mensagem é muito longa (máximo 500 caracteres).") end); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then
            pcall(function() fbStatus:SetText("Links não são permitidos.") end); return
        end
        pcall(function() fbStatus:SetText("Enviando...") end)
        task.spawn(function()
            local sok, err = sendFeedback(ftype, msg)
            if sok then
                lastFeedback = tick()
                pcall(function() fbStatus:SetText("Enviado. Obrigado!") end)
                pcall(function() Opt.FeedbackMsg:SetValue("") end)
                log("Seu feedback foi enviado. Obrigado!")
            else
                pcall(function() fbStatus:SetText(FB_ERRMAP[err] or ("Falha ao enviar: " .. tostring(err))) end)
            end
        end)
    end,
})
FG:AddLabel("Máximo de 3 mensagens por hora. Sem links ou menções.", true)

freeBuy = Toggles.s_freebuy and Toggles.s_freebuy.Value ~= false
installActionHook()

